.cookie-consent {
  position: fixed;
  right: clamp(16px, 3vw, 36px);
  bottom: clamp(16px, 3vw, 36px);
  z-index: 1300;
  width: min(570px, calc(100vw - 32px));
  padding: 18px;
  display: grid;
  grid-template-columns: 68px minmax(0, 1fr);
  gap: 10px 16px;
  align-items: center;
  color: #f8f7ff;
  border: 1px solid rgba(196, 181, 253, 0.24);
  border-radius: 22px;
  background: linear-gradient(145deg, rgba(15, 10, 31, 0.97), rgba(49, 46, 129, 0.96));
  box-shadow: 0 24px 70px rgba(15, 10, 31, 0.42);
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 0.25s ease, transform 0.25s ease;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.cookie-consent.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.cookie-consent-icon {
  width: 68px;
  height: 68px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(196, 181, 253, 0.2);
  border-radius: 20px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.1), rgba(124, 58, 237, 0.1));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.11);
}

.cookie-consent-icon svg {
  width: 62px;
  height: 62px;
  overflow: visible;
}

.cookie-consent h2 {
  margin: 0 0 6px;
  color: #fff;
  font-family: 'Montserrat', sans-serif;
  font-size: 1.05rem;
  line-height: 1.3;
}

.cookie-consent p {
  margin: 0;
  color: rgba(248, 247, 255, 0.76);
  font-size: 0.86rem;
  line-height: 1.55;
}

.cookie-consent-actions {
  grid-column: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.cookie-consent button {
  min-height: 44px;
  padding: 10px 16px;
  border-radius: 13px;
  font: 700 0.84rem 'Inter', sans-serif;
  cursor: pointer;
}

.cookie-consent-accept {
  color: #fff;
  border: 1px solid transparent;
  background: linear-gradient(135deg, #6d28d9, #8b5cf6);
  box-shadow: 0 10px 24px rgba(124, 58, 237, 0.28);
}

.cookie-consent-reject {
  color: #ddd6fe;
  border: 1px solid rgba(221, 214, 254, 0.22);
  background: rgba(255, 255, 255, 0.06);
}

.cookie-settings-button {
  padding: 0;
  color: inherit;
  border: 0;
  background: none;
  font: inherit;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

@media (max-width: 640px) {
  .cookie-consent {
    left: 12px;
    right: 12px;
    bottom: calc(12px + env(safe-area-inset-bottom));
    width: auto;
    padding: 18px;
    grid-template-columns: 58px minmax(0, 1fr);
    gap: 10px 14px;
  }

  .cookie-consent-icon {
    width: 58px;
    height: 58px;
    border-radius: 17px;
  }

  .cookie-consent-icon svg {
    width: 54px;
    height: 54px;
  }

  .cookie-consent-actions {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .cookie-consent button {
    font-size: 0.8rem;
  }
}

@media (max-width: 390px) {
  .cookie-consent-actions {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cookie-consent {
    transition: none;
  }
}

:root{
  --sp-primary:#7c3aed;
  --sp-primary-dark:#5b21b6;
  --sp-accent:#a78bfa;
  --sp-accent-light:#ddd6fe;
  --sp-dark:#0f0a1f;
  --sp-dark-2:#17102d;
  --sp-dark-3:#211746;
  --sp-text:#f8f7ff;
  --sp-muted:rgba(248,247,255,.68);
  --sp-line:rgba(255,255,255,.1);
  --sp-gradient:linear-gradient(135deg,#5b21b6 0%,#7c3aed 50%,#8b5cf6 100%);
}

*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  min-width:320px;
  overflow-x:hidden;
  color:var(--sp-text);
  background:
    radial-gradient(circle at 82% 8%,rgba(124,58,237,.18),transparent 28rem),
    radial-gradient(circle at 8% 38%,rgba(49,46,129,.18),transparent 34rem),
    var(--sp-dark);
  font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
  line-height:1.65;
}
body::before{
  position:fixed;
  inset:0;
  z-index:-1;
  background-image:linear-gradient(rgba(255,255,255,.018) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.018) 1px,transparent 1px);
  background-size:72px 72px;
  mask-image:linear-gradient(to bottom,black,transparent 72%);
  content:'';
  pointer-events:none;
}
a{color:inherit}
img{max-width:100%}
button,input,textarea{font:inherit}
button,a{-webkit-tap-highlight-color:transparent}

.sp-skip{
  position:fixed;
  top:12px;
  left:12px;
  z-index:1000;
  padding:.75rem 1rem;
  border-radius:12px;
  color:#fff;
  background:var(--sp-primary);
  transform:translateY(-150%);
}
.sp-skip:focus{transform:none}

.sp-header{
  position:fixed;
  top:0;
  left:0;
  right:0;
  z-index:100;
  border-bottom:1px solid transparent;
  transition:background .35s,border-color .35s,box-shadow .35s;
}
.sp-header.is-scrolled{
  border-color:rgba(255,255,255,.08);
  background:rgba(10,6,20,.88);
  -webkit-backdrop-filter:blur(18px);
  backdrop-filter:blur(18px);
  box-shadow:0 16px 50px rgba(0,0,0,.2);
}
.sp-nav{
  width:min(1380px,90%);
  min-height:88px;
  margin:0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:2rem;
}
.sp-logo{
  text-decoration:none;
  font-family:'Montserrat',sans-serif;
  font-size:1.7rem;
  font-weight:900;
  letter-spacing:2.5px;
  background:var(--sp-gradient);
  -webkit-background-clip:text;
  background-clip:text;
  color:transparent;
}
.sp-nav-links{display:flex;align-items:center;gap:2rem}
.sp-nav-links a{
  color:rgba(255,255,255,.76);
  font-size:.92rem;
  font-weight:600;
  text-decoration:none;
  transition:color .25s;
}
.sp-nav-links a:hover{color:#fff}
.sp-nav-links .sp-nav-cta{
  padding:.75rem 1.35rem;
  border:1px solid rgba(196,181,253,.25);
  border-radius:999px;
  color:#fff;
  background:rgba(124,58,237,.18);
}
.sp-menu{
  display:none;
  width:46px;
  height:46px;
  border:1px solid var(--sp-line);
  border-radius:14px;
  background:rgba(255,255,255,.05);
}
.sp-menu span{
  display:block;
  width:21px;
  height:2px;
  margin:5px auto;
  border-radius:2px;
  background:#fff;
}

.sp-main{overflow:hidden}
.sp-container{width:min(1180px,90%);margin:0 auto}
.sp-hero{
  position:relative;
  min-height:760px;
  padding:150px 0 90px;
  display:flex;
  align-items:center;
}
.sp-hero::after{
  position:absolute;
  top:13%;
  right:-15%;
  width:520px;
  height:520px;
  border-radius:50%;
  background:rgba(124,58,237,.12);
  filter:blur(80px);
  content:'';
  pointer-events:none;
}
.sp-breadcrumbs{
  margin-bottom:2rem;
  display:flex;
  flex-wrap:wrap;
  gap:.55rem;
  color:rgba(255,255,255,.48);
  font-size:.84rem;
}
.sp-breadcrumbs a{text-decoration:none;color:var(--sp-accent-light)}
.sp-hero-grid{
  display:grid;
  grid-template-columns:minmax(0,1.2fr) minmax(330px,.8fr);
  gap:6rem;
  align-items:center;
}
.sp-eyebrow,.sp-section-label{
  display:inline-flex;
  align-items:center;
  gap:.6rem;
  color:var(--sp-accent-light);
  font-size:.78rem;
  font-weight:700;
  letter-spacing:1.8px;
  text-transform:uppercase;
}
.sp-eyebrow::before,.sp-section-label::before{
  width:8px;
  height:8px;
  border-radius:50%;
  background:#8b5cf6;
  box-shadow:0 0 18px rgba(139,92,246,.8);
  content:'';
}
.sp-hero h1{
  max-width:820px;
  margin:1.2rem 0 1.5rem;
  font-family:'Montserrat',sans-serif;
  font-size:clamp(2.7rem,5.5vw,5rem);
  font-weight:900;
  letter-spacing:-2.5px;
  line-height:1.05;
}
.sp-lead{
  max-width:760px;
  color:var(--sp-muted);
  font-size:clamp(1.05rem,1.7vw,1.28rem);
  line-height:1.75;
}
.sp-geo{
  margin-top:1.5rem;
  display:flex;
  align-items:flex-start;
  gap:.7rem;
  color:rgba(255,255,255,.55);
  font-size:.9rem;
}
.sp-geo-dot{
  width:8px;
  height:8px;
  margin-top:.55rem;
  flex:0 0 auto;
  border-radius:50%;
  background:#10b981;
  box-shadow:0 0 15px rgba(16,185,129,.65);
}
.sp-actions{margin-top:2.25rem;display:flex;flex-wrap:wrap;gap:1rem}
.sp-btn{
  min-height:56px;
  padding:0 1.6rem;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:.65rem;
  border:1px solid transparent;
  border-radius:999px;
  font-weight:700;
  text-decoration:none;
  transition:transform .3s,box-shadow .3s,border-color .3s,background .3s;
}
.sp-btn:hover{transform:translateY(-3px)}
.sp-btn-primary{color:#fff;background:var(--sp-gradient);box-shadow:0 15px 38px rgba(124,58,237,.3)}
.sp-btn-primary:hover{box-shadow:0 22px 48px rgba(124,58,237,.42)}
.sp-btn-secondary{border-color:rgba(255,255,255,.16);background:rgba(255,255,255,.045)}
.sp-btn-secondary:hover{border-color:rgba(196,181,253,.35);background:rgba(255,255,255,.075)}

.sp-hero-card{
  position:relative;
  padding:2.2rem;
  border:1px solid rgba(255,255,255,.12);
  border-radius:32px;
  background:linear-gradient(145deg,rgba(255,255,255,.085),rgba(255,255,255,.025));
  -webkit-backdrop-filter:blur(22px);
  backdrop-filter:blur(22px);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 32px 80px rgba(0,0,0,.28);
}
.sp-hero-card::before{
  position:absolute;
  inset:-1px;
  z-index:-1;
  border-radius:32px;
  background:linear-gradient(135deg,rgba(167,139,250,.2),transparent 42%,rgba(124,58,237,.12));
  content:'';
}
.sp-service-icon{
  width:116px;
  height:116px;
  margin-bottom:1.35rem;
  display:flex;
  align-items:center;
  justify-content:center;
  border:1px solid rgba(196,181,253,.14);
  border-radius:30px;
  background:radial-gradient(circle at 35% 25%,rgba(255,255,255,.16),rgba(124,58,237,.08));
  box-shadow:0 18px 38px rgba(0,0,0,.22);
}
.sp-service-icon img{width:108px;height:108px;object-fit:contain;filter:drop-shadow(0 12px 14px rgba(0,0,0,.25))}
.sp-card-title{font-family:'Montserrat',sans-serif;font-size:1.25rem;font-weight:800}
.sp-card-list{margin-top:1.25rem;display:grid;gap:.85rem;list-style:none}
.sp-card-list li{display:flex;align-items:flex-start;gap:.75rem;color:rgba(255,255,255,.67);font-size:.93rem}
.sp-card-list li::before{
  width:20px;
  height:20px;
  margin-top:.15rem;
  flex:0 0 auto;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:50%;
  color:#c4b5fd;
  background:rgba(124,58,237,.2);
  content:'✓';
  font-size:.7rem;
  font-weight:900;
}

.sp-section{position:relative;padding:100px 0}
.sp-section-soft{
  border-top:1px solid rgba(255,255,255,.06);
  border-bottom:1px solid rgba(255,255,255,.06);
  background:linear-gradient(180deg,rgba(255,255,255,.025),rgba(255,255,255,.012));
}
.sp-section-heading{max-width:800px;margin-bottom:3rem}
.sp-section h2{
  margin:.9rem 0 1.15rem;
  font-family:'Montserrat',sans-serif;
  font-size:clamp(2rem,4vw,3.25rem);
  font-weight:850;
  letter-spacing:-1.5px;
  line-height:1.14;
}
.sp-section-intro{color:var(--sp-muted);font-size:1.08rem;line-height:1.8}
.sp-prose{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.4rem}
.sp-prose p{
  padding:1.6rem;
  border:1px solid rgba(255,255,255,.075);
  border-radius:22px;
  color:rgba(255,255,255,.68);
  background:rgba(255,255,255,.025);
}

.sp-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.2rem}
.sp-info-card{
  min-height:220px;
  padding:1.7rem;
  border:1px solid rgba(255,255,255,.09);
  border-radius:25px;
  background:linear-gradient(145deg,rgba(255,255,255,.05),rgba(255,255,255,.018));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.05);
  transition:transform .35s,border-color .35s,box-shadow .35s;
}
.sp-info-card:hover{
  border-color:rgba(167,139,250,.28);
  transform:translateY(-5px);
  box-shadow:0 20px 45px rgba(0,0,0,.2);
}
.sp-card-number{
  width:38px;
  height:38px;
  margin-bottom:1.2rem;
  display:flex;
  align-items:center;
  justify-content:center;
  border:1px solid rgba(196,181,253,.16);
  border-radius:12px;
  color:#c4b5fd;
  background:rgba(124,58,237,.14);
  font-size:.82rem;
  font-weight:800;
}
.sp-info-card h3{margin-bottom:.65rem;font-family:'Montserrat',sans-serif;font-size:1.1rem;line-height:1.35}
.sp-info-card p{color:rgba(255,255,255,.58);font-size:.93rem;line-height:1.7}

.sp-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}
.sp-step{
  position:relative;
  padding:1.6rem;
  border:1px solid rgba(255,255,255,.085);
  border-radius:24px;
  background:rgba(255,255,255,.025);
}
.sp-step::after{
  position:absolute;
  top:37px;
  right:-1.05rem;
  width:1.1rem;
  height:1px;
  background:linear-gradient(90deg,rgba(167,139,250,.45),transparent);
  content:'';
}
.sp-step:last-child::after{display:none}
.sp-step span{color:#8b5cf6;font-family:'Montserrat',sans-serif;font-size:1.85rem;font-weight:900}
.sp-step h3{margin:.65rem 0 .55rem;font-size:1rem}
.sp-step p{color:rgba(255,255,255,.56);font-size:.9rem}

.sp-note{
  margin-top:2rem;
  padding:1.5rem 1.7rem;
  display:flex;
  align-items:flex-start;
  gap:1rem;
  border:1px solid rgba(139,92,246,.22);
  border-radius:22px;
  color:rgba(255,255,255,.67);
  background:linear-gradient(135deg,rgba(124,58,237,.14),rgba(255,255,255,.025));
}
.sp-note-mark{color:#a78bfa;font-size:1.25rem;font-weight:900}

.sp-faq{display:grid;gap:.9rem;max-width:920px}
.sp-faq details{
  border:1px solid rgba(255,255,255,.09);
  border-radius:20px;
  background:rgba(255,255,255,.028);
  overflow:hidden;
}
.sp-faq summary{
  min-height:76px;
  padding:1.2rem 1.5rem;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:1rem;
  cursor:pointer;
  font-family:'Montserrat',sans-serif;
  font-weight:700;
  list-style:none;
}
.sp-faq summary::-webkit-details-marker{display:none}
.sp-faq summary::after{
  width:34px;
  height:34px;
  flex:0 0 auto;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:50%;
  color:#c4b5fd;
  background:rgba(124,58,237,.16);
  content:'+';
  font-size:1.35rem;
  transition:transform .3s,background .3s;
}
.sp-faq details[open] summary::after{background:var(--sp-primary);transform:rotate(45deg)}
.sp-faq-answer{padding:0 1.5rem 1.4rem;color:rgba(255,255,255,.62);line-height:1.75}

.sp-related{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}
.sp-related a{
  min-height:130px;
  padding:1.5rem;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  border:1px solid rgba(255,255,255,.09);
  border-radius:22px;
  text-decoration:none;
  background:rgba(255,255,255,.025);
  transition:transform .3s,border-color .3s,background .3s;
}
.sp-related a:hover{border-color:rgba(167,139,250,.3);background:rgba(124,58,237,.09);transform:translateY(-4px)}
.sp-related strong{font-family:'Montserrat',sans-serif;font-size:1.05rem}
.sp-related span{color:#a78bfa;font-size:1.25rem}

.sp-contact{padding:110px 0}
.sp-contact-panel{
  position:relative;
  padding:4rem;
  display:grid;
  grid-template-columns:minmax(0,1.1fr) minmax(300px,.9fr);
  gap:4rem;
  align-items:center;
  overflow:hidden;
  border:1px solid rgba(255,255,255,.11);
  border-radius:34px;
  background:linear-gradient(135deg,rgba(91,33,182,.42),rgba(33,23,70,.72));
  box-shadow:0 35px 90px rgba(0,0,0,.28);
}
.sp-contact-panel::after{
  position:absolute;
  right:-100px;
  bottom:-170px;
  width:430px;
  height:430px;
  border-radius:50%;
  background:rgba(139,92,246,.18);
  content:'';
  pointer-events:none;
}
.sp-contact h1,.sp-contact h2{margin:0 0 1rem;font-family:'Montserrat',sans-serif;font-size:clamp(2rem,4vw,3.2rem);font-weight:850;line-height:1.14}
.sp-contact p{color:rgba(255,255,255,.68);font-size:1.06rem}
.sp-contact-actions{position:relative;z-index:1;display:grid;gap:.9rem}
.sp-contact-actions .sp-btn{width:100%;border-color:rgba(255,255,255,.13);background:rgba(255,255,255,.08)}
.sp-contact-actions .sp-btn:hover{background:rgba(255,255,255,.13)}

.sp-footer{
  padding:2.5rem 5%;
  border-top:1px solid rgba(255,255,255,.07);
  color:rgba(255,255,255,.43);
  background:#090511;
}
.sp-footer-inner{
  width:min(1180px,100%);
  margin:0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:1.5rem;
  font-size:.86rem;
}
.sp-footer a{color:rgba(255,255,255,.58);text-decoration:none}
.sp-footer-links{display:flex;flex-wrap:wrap;gap:1.2rem}
.sp-error-page .sp-contact{min-height:100vh;display:flex;align-items:center}
.sp-error-page .sp-contact-panel{width:100%}

@media(max-width:1000px){
  .sp-hero-grid{grid-template-columns:1fr;gap:3.5rem}
  .sp-hero-card{max-width:540px}
  .sp-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .sp-steps{grid-template-columns:repeat(2,minmax(0,1fr))}
  .sp-step::after{display:none}
  .sp-contact-panel{grid-template-columns:1fr;gap:2.5rem}
}

@media(max-width:760px){
  .sp-nav{min-height:74px}
  .sp-menu{display:block}
  .sp-nav-links{
    position:fixed;
    top:74px;
    left:5%;
    right:5%;
    padding:1.2rem;
    display:none;
    flex-direction:column;
    align-items:stretch;
    gap:.4rem;
    border:1px solid rgba(255,255,255,.1);
    border-radius:20px;
    background:rgba(10,6,20,.97);
    box-shadow:0 24px 60px rgba(0,0,0,.38);
  }
  .sp-nav-links.is-open{display:flex}
  .sp-nav-links a{padding:.8rem 1rem}
  .sp-nav-links .sp-nav-cta{text-align:center}
  .sp-hero{min-height:auto;padding:120px 0 75px}
  .sp-hero h1{font-size:clamp(2.35rem,12vw,3.5rem);letter-spacing:-1.5px}
  .sp-section{padding:76px 0}
  .sp-prose,.sp-grid,.sp-steps,.sp-related{grid-template-columns:1fr}
  .sp-info-card{min-height:auto}
  .sp-contact{padding:76px 0}
  .sp-contact-panel{padding:2.2rem 1.4rem;border-radius:26px}
  .sp-footer-inner{flex-direction:column;align-items:flex-start}
}

@media(max-width:460px){
  .sp-logo{font-size:1.4rem}
  .sp-actions{flex-direction:column}
  .sp-btn{width:100%}
  .sp-hero-card{padding:1.5rem;border-radius:25px}
  .sp-service-icon{width:94px;height:94px;border-radius:25px}
  .sp-service-icon img{width:88px;height:88px}
  .sp-section-heading{margin-bottom:2.2rem}
}

@media(prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{scroll-behavior:auto!important;transition-duration:.01ms!important;animation-duration:.01ms!important;animation-iteration-count:1!important}
}

